inline const RecoveredLevelSetup* findLevelSetup(u32 stageId) {
    for (const RecoveredLevelSetup& row : kRecoveredLevelSetups)
        if (row.stageId == stageId) return &row;
    return nullptr;
}

inline const RecoveredLevelSetup* findLevelSetupByConstructor(u32 va) {
    for (const RecoveredLevelSetup& row : kRecoveredLevelSetups)
        if (row.constructorVa == va) return &row;
    return nullptr;
}

inline bool levelSetupHasLoopCue(const RecoveredLevelSetup& row,
                                  std::string_view cue) {
    for (u8 i = 0; i < row.loopCueCount; ++i)
        if (row.loopCues[i] == cue) return true;
    return false;
}

inline bool levelSetupHasIntroCue(const RecoveredLevelSetup& row,
                                   std::string_view cue) {
    for (u8 i = 0; i < row.introCueCount; ++i)
        if (row.introCues[i] == cue) return true;
    return false;
}

inline const RecoveredLevelSetup* findLevelSetupByLoopCue(
    std::string_view cue) {
    for (const RecoveredLevelSetup& row : kRecoveredLevelSetups)
        if (levelSetupHasLoopCue(row, cue)) return &row;
    return nullptr;
}

inline const RecoveredLevelSetup* findLevelSetupByIntroCue(
    std::string_view cue) {
    for (const RecoveredLevelSetup& row : kRecoveredLevelSetups)
        if (levelSetupHasIntroCue(row, cue)) return &row;
    return nullptr;
}

